use super::*;
use semio_framework_value::{RetireOwned,retained_clone::RetainedCloneSource};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn source<T:RetireOwned+Sync>(v:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let g=grant(RetirementDemand{copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()});RetainedCloneSource::admit_owned(v,(),g).unwrap_or_else(|(e,_,_)|panic!("{e}")).0}
fn close_source<T:RetireOwned+Sync>(s:&mut RetainedCloneSource<T>){while !s.terminal_is_empty(){let d=s.next_close_demand(256).unwrap();s.close_step(grant(d)).unwrap();}}
fn observe(g:RetainedCloneGrant,f:impl FnOnce()->RetainedCloneStep)->RetainedCloneStep{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!heap.overflowed);assert_eq!(heap.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress().released_bytes);assert!(step.progress().fits(g));step}
fn close(owner:&mut FrameSelectionPlan){owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){return}let d=owner.close_demand(256).unwrap();assert_eq!(observe(Default::default(),||owner.close_step(Default::default()).unwrap()).progress(),Default::default());observe(grant(d),||owner.close_step(grant(d)).unwrap());}panic!("numeric original selection close stalled")}
fn failure(value:&str)->BatchFailure{match value{"envelope"=>BatchFailure::Envelope,"empty"=>BatchFailure::Empty,"duplicate"=>BatchFailure::Duplicate,"page-missing"=>BatchFailure::PageMissing,"none-unlocked"=>BatchFailure::NoneUnlocked,"bounds"=>BatchFailure::Bounds,_=>unreachable!()}}
#[test]
fn numeric_original_target_order_lock_bounds_and_heap_receipts_share_neutral_witnesses(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let event:LayoutMutation=decode(&row["mutation"]);let mut original:LayoutSnapshot=decode(&row["before"]);if row["beforeXNegativeZero"]==true{match &mut original.pages[0].frames[0]{Frame::Rect{bounds,..}|Frame::Text{bounds,..}|Frame::Image{bounds,..}=>bounds.x=-0.0}}
  for cut in std::iter::once(usize::MAX).chain(fixture["cuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize)){
   let mut mutation=source(event.clone());let mut base=source(original.clone());let mut owner=FrameSelectionPlan::default();
   for turn in 0..cut{if owner.ready(){break}assert!(turn<100000);let d=owner.demand(mutation.borrow(),base.borrow()).unwrap();let g=grant(d);assert_eq!(observe(Default::default(),||owner.advance(mutation.borrow(),base.borrow(),Default::default()).unwrap()).progress(),Default::default());for short in[RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_depth:d.depth-1,..g}]{if short==g{continue}assert_eq!(observe(short,||owner.advance(mutation.borrow(),base.borrow(),short).unwrap()).progress(),Default::default());}observe(g,||owner.advance(mutation.borrow(),base.borrow(),g).unwrap());}
   if cut==usize::MAX{assert!(owner.ready());let expected=&row["expected"];assert_eq!(owner.failure,expected["error"].as_str().map(failure));if owner.failure.is_none(){assert_eq!(owner.page,expected["page"].as_u64().unwrap()as usize);assert_eq!(owner.movable,expected["movable"].as_u64().unwrap()as usize);assert_eq!(owner.missing(),decode::<Vec<usize>>(&expected["missing"]));assert_eq!(owner.locked(),decode::<Vec<usize>>(&expected["locked"]));let rows=expected["changed"].as_array().unwrap();assert_eq!(owner.changed().len(),rows.len());for(actual,expected)in owner.changed().iter().zip(rows){assert_eq!(actual.frame,expected["frame"].as_u64().unwrap()as usize);assert_eq!(actual.target,expected["target"].as_u64().unwrap()as usize);for(index,key)in["x","y","w","h","rotation"].into_iter().enumerate(){if let Some(tolerance)=row["tolerance"].as_f64(){assert!((actual.bounds[index]-expected["bounds"][key].as_f64().unwrap()).abs()<tolerance)}else{assert_eq!(actual.bounds[index].to_bits(),expected["bounds"][key].as_f64().unwrap().to_bits());}}}}else if expected.get("duplicate").is_some(){assert_eq!(owner.duplicate,expected["duplicate"].as_u64().map(|v|v as usize));}}
   assert_eq!(mutation.borrow().get(),&event);assert_eq!(base.borrow().get(),&original);close(&mut owner);close_source(&mut mutation);close_source(&mut base);
  }
 }
}
